parameters.jsCode:
const item = $input.first().json;
const sourceTitle = item.body?.title || item.title || 'Transformative AI & Agency Strategies';
const rawContent = item.body?.content || item.content || item.body?.text || 'Content creation and AI automation are transforming how modern agencies scale.';
const brandTone = item.body?.tone || item.tone || 'Authoritative, engaging, data-backed and inspiring';
const clientName = item.body?.client || item.client || 'Agency Client';

return [{
  json: {
    sourceTitle,
    rawContent: rawContent.slice(0, 10000),
    brandTone,
    clientName,
    jobId: 'REPURPOSE-' + Date.now(),
    submittedAt: new Date().toISOString()
  }
}];

parameters.text:
=You are an elite social media growth director. Repurpose this source content into 5 tailored channel assets:

Title: {{ $json.sourceTitle }}
Client: {{ $json.clientName }}
Tone: {{ $json.brandTone }}
Source Content:
{{ $json.rawContent }}

Generate pure JSON containing:
1. 'linkedin_post': Full thought-leadership post (Hook line, 4 structured takeaways, actionable conclusion, 3 relevant hashtags).
2. 'twitter_thread': Array of 4-6 tweets (Tweet 1 is a viral hook; last tweet is a CTA).
3. 'instagram_caption': High-engagement caption with line breaks, emojis, and a 'dalle_image_prompt' for generating the matching visual.
4. 'tiktok_script': 60s short video script formatted with timestamps, [Visual Action] cues, and spoken voiceover text.
5. 'facebook_post': Community-oriented conversational post asking a discussion question.
6. 'seo_keywords': Array of 5 target keywords.

parameters.jsCode:
const item = $input.first();
const initial = $('Prepare Source Text & Brand Persona').first().json;
let assets = item.json.output || item.json.text || item.json;

if (typeof assets === 'string') {
  try {
    assets = JSON.parse(assets);
  } catch (e) {
    const match = assets.match(/\{[\s\S]*\}/);
    if (match) assets = JSON.parse(match[0]);
  }
}

return [{
  json: {
    jobId: initial.jobId,
    clientName: initial.clientName,
    sourceTitle: initial.sourceTitle,
    linkedinPost: assets.linkedin_post || '',
    twitterThread: assets.twitter_thread || [],
    instagramCaption: assets.instagram_caption || '',
    dallePrompt: assets.dalle_image_prompt || 'Modern 3D render representing agency growth, clean futuristic aesthetics, vibrant gradient lighting',
    tiktokScript: assets.tiktok_script || '',
    facebookPost: assets.facebook_post || '',
    seoKeywords: assets.seo_keywords || [],
    status: 'READY_FOR_APPROVAL',
    generatedAt: new Date().toISOString()
  }
}];

